/**
 * ============================================================================
 * FILE: components/AIMarketBriefPanel.tsx
 * ============================================================================
 * FEATURE OVERVIEW:
 * Quantitative Gemini AI Market Intelligence & Sentiment Synthesis Panel.
 *
 * USE CASES:
 * 1. Displaying structured institutional analysis generated by Gemini
 *    (`gemini-4-hydrogen`) from the current Context.dev company news feed.
 * 2. Highlighting overall institutional sentiment (Bullish, Neutral, Bearish),
 *    signal conviction score, executive summary, key operational catalysts,
 *    and regulatory/execution risk factors.
 * ============================================================================
 */

'use client';

import React from 'react';
import {
  TrendingUp,
  TrendingDown,
  Minus,
  AlertTriangle,
  RefreshCw,
} from 'lucide-react';
import type { AIMarketBriefResponse } from '@/lib/gemini-service';
import { BrandFoxLogo } from '@/components/BrandFoxLogo';
import { useLanguage } from '@/components/LanguageProvider';
import {
  translateSentimentLabel,
  translateSentimentTooltip,
} from '@/lib/i18n';
import { logFunctionCall } from '@/lib/logger';

export interface AIMarketBriefPanelProps {
  companyLabel: string;
  brief: AIMarketBriefResponse | null;
  isLoading: boolean;
  error: string | null;
  onGenerate: () => void;
}

/**
 * Renders the full-width AI Analyst Assessment with Overall Evaluation
 * and side-by-side Positive Catalysts (Bullish) vs. Risks & Headwinds (Bearish).
 */
export function AIMarketBriefPanel({
  companyLabel,
  brief,
  isLoading,
  error,
  onGenerate,
}: AIMarketBriefPanelProps) {
  const { locale, t } = useLanguage();

  return (
    <section
      id="briefing"
      aria-label={t.aiBrief.headerTitle}
      className="rounded-xl bg-[#0d1b33] border border-[#212c42] p-6 mb-6"
    >
      <div className="flex flex-wrap items-center justify-between gap-4 pb-4 mb-5 border-b border-[#212c42]">
        <div className="flex items-center gap-3">
          <BrandFoxLogo size={22} framed alt="" />
          <div>
            <h2 className="text-base font-bold text-white">
              {t.aiBrief.headerTitle}: {companyLabel}
            </h2>
            <p className="text-xs text-slate-400">
              {t.aiBrief.headerSubtitle}
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={() => {
            logFunctionCall('AIMarketBriefPanel.onGenerate', { companyLabel });
            onGenerate();
          }}
          disabled={isLoading}
          className="flex items-center gap-1.5 px-3.5 py-2 text-xs font-semibold text-white bg-[#09a4ff] hover:bg-[#49afe9] disabled:opacity-50 rounded-lg transition-colors whitespace-nowrap shrink-0 cursor-pointer"
        >
          <RefreshCw
            className={`w-3.5 h-3.5 ${isLoading ? 'animate-spin' : ''}`}
          />
          <span>
            {isLoading ? t.aiBrief.synthesizing : t.aiBrief.refreshAnalysis}
          </span>
        </button>
      </div>

      {error && (
        <div className="p-4 rounded-lg bg-rose-950/40 border border-rose-500/40 text-xs text-rose-200 mb-4">
          {error}
        </div>
      )}

      {isLoading ? (
        <div className="space-y-5 animate-pulse">
          <div className="h-16 w-full bg-[#162747] rounded-lg" />
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2.5">
              <div className="h-4 w-40 bg-[#162747] rounded" />
              <div className="h-10 w-full bg-[#162747] rounded" />
              <div className="h-10 w-full bg-[#162747] rounded" />
            </div>
            <div className="space-y-2.5">
              <div className="h-4 w-40 bg-[#162747] rounded" />
              <div className="h-10 w-full bg-[#162747] rounded" />
              <div className="h-10 w-full bg-[#162747] rounded" />
            </div>
          </div>
        </div>
      ) : !brief ? (
        <div className="py-8 text-center border border-dashed border-[#212c42] rounded-lg px-4">
          <div className="flex justify-center mb-2.5">
            <BrandFoxLogo size={26} framed alt="" />
          </div>
          <p className="text-sm font-medium text-white mb-1">
            {t.aiBrief.headerTitle}
          </p>
          <p className="text-xs text-slate-400 mb-4">
            {t.aiBrief.emptyStatePrompt}
          </p>
          <button
            type="button"
            onClick={onGenerate}
            className="px-4 py-2 text-xs font-semibold text-white bg-[#09a4ff] hover:bg-[#49afe9] rounded-lg transition-colors whitespace-nowrap shrink-0 cursor-pointer"
          >
            {t.aiBrief.generateBriefCta}
          </button>
        </div>
      ) : (
        <div className="space-y-6">
          {/* Overall Assessment Strip */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
            <div className="lg:col-span-3 flex items-center justify-between lg:flex-col lg:items-start gap-2 py-3 px-4 rounded-lg bg-[#091326] border border-[#212c42] font-mono-tabular">
              <div>
                <div className="text-xs text-slate-400 mb-0.5">
                  {t.aiBrief.overallVerdict}
                </div>
                <div
                  title={translateSentimentTooltip(brief.sentiment, locale)}
                  className={`inline-flex items-center gap-1.5 text-base font-bold ${
                    brief.sentiment === 'Bullish'
                      ? 'text-emerald-400'
                      : brief.sentiment === 'Bearish'
                        ? 'text-rose-400'
                        : 'text-[#49afe9]'
                  }`}
                >
                  {brief.sentiment === 'Bullish' ? (
                    <TrendingUp className="w-4 h-4" aria-hidden="true" />
                  ) : brief.sentiment === 'Bearish' ? (
                    <TrendingDown className="w-4 h-4" aria-hidden="true" />
                  ) : (
                    <Minus className="w-4 h-4" aria-hidden="true" />
                  )}
                  <span>{translateSentimentLabel(brief.sentiment, locale)}</span>
                </div>
              </div>

              <div className="text-right lg:text-left">
                <div className="text-xs text-slate-400">
                  {t.aiBrief.signalConviction}
                </div>
                <div className="text-sm font-bold text-white">
                  {brief.confidenceScore}%
                </div>
              </div>
            </div>

            <div className="lg:col-span-9 space-y-2">
              <h3 className="text-xs font-semibold text-[#49afe9]">
                {t.aiBrief.overallVerdict}
              </h3>
              <p className="text-sm text-slate-200 leading-relaxed">
                {brief.executiveSummary}
              </p>
              <p className="text-xs text-slate-400 leading-relaxed">
                <span className="text-slate-300 font-medium">
                  {t.aiBrief.sectorAndPeerImpact}:{' '}
                </span>
                {brief.sectorImpact}
              </p>
            </div>
          </div>

          {/* Side-by-Side Positive Catalysts vs. Risks & Headwinds */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-5 border-t border-[#212c42]">
            {/* Left Column: Positive Catalysts (Bullish Drivers) */}
            <div>
              <div className="flex items-center gap-2 text-xs font-semibold text-emerald-400 mb-3">
                <TrendingUp className="w-4 h-4" aria-hidden="true" />
                <span>
                  {t.aiBrief.positiveCatalysts} ({t.aiBrief.bullCaseTag})
                </span>
              </div>

              {brief.keyCatalysts.length > 0 ? (
                <ul className="divide-y divide-[#212c42]">
                  {brief.keyCatalysts.map((cat, idx) => (
                    <li
                      key={idx}
                      className="py-2.5 first:pt-0 last:pb-0 flex items-start gap-3 text-xs text-slate-200 leading-relaxed"
                    >
                      <span className="text-emerald-400 font-mono-tabular font-semibold shrink-0">
                        0{idx + 1}.
                      </span>
                      <span>{cat}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-xs text-slate-400">
                  {locale === 'ko'
                    ? '현재 기사 묶음에서 주요 상승 모멘텀이 포착되지 않았습니다.'
                    : 'No major upside catalysts highlighted in the current article batch.'}
                </p>
              )}
            </div>

            {/* Right Column: Risks & Headwinds (Bearish Factors) */}
            <div>
              <div className="flex items-center gap-2 text-xs font-semibold text-rose-400 mb-3">
                <AlertTriangle className="w-4 h-4" aria-hidden="true" />
                <span>
                  {t.aiBrief.risksAndHeadwinds} ({t.aiBrief.bearCaseTag})
                </span>
              </div>

              {brief.riskFactors.length > 0 ? (
                <ul className="divide-y divide-[#212c42]">
                  {brief.riskFactors.map((risk, idx) => (
                    <li
                      key={idx}
                      className="py-2.5 first:pt-0 last:pb-0 flex items-start gap-3 text-xs text-slate-200 leading-relaxed"
                    >
                      <span className="text-rose-400 font-mono-tabular font-semibold shrink-0">
                        0{idx + 1}.
                      </span>
                      <span>{risk}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-xs text-slate-400">
                  {locale === 'ko'
                    ? '현재 기사 묶음에서 중대한 하방 리스크 요인이 포착되지 않았습니다.'
                    : 'No material downside risks highlighted in the current article batch.'}
                </p>
              )}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}
